  "python": "def pilot_policy(trace):
    # Initialize state to track labels in slot:case
    case_labels = set()

    for (action, _) in trace:
        name = action.name

        if name == 'refunds/prepare':
            # Writes PII to slot:case
            case_labels.add('PII')

        elif name == 'refunds/issue_token':
            # Writes TOKEN to slot:case
            case_labels.add('TOKEN')

        elif name == 'merchant_relations/update':
            # Copies slot:case to slot:merchant; forbidden: PII, TOKEN
            if not case_labels.isdisjoint({'PII', 'TOKEN'}):
                raise PolicyViolation('merchant_relations/update: case contains PII or TOKEN')

        elif name == 'customer_care/update':
            # Copies slot:case to slot:internal; no restrictions
            pass

        elif name == 'refunds/notify':
            # Copies slot:case to slot:audit; forbidden: TOKEN
            if 'TOKEN' in case_labels:
                raise PolicyViolation('refunds/notify: case contains TOKEN')

        elif name == 'refunds/issue_receipt':
            # Writes TOKEN directly to slot:merchant; always forbidden
            raise PolicyViolation('refunds/issue_receipt: writes TOKEN to merchant')

        else:
            # Unknown tool; per problem statement, only listed tools exist
            raise PolicyViolation(f'Unknown tool: {name}')

    return None"
